css:
@media print {
    body { margin: 0; padding: 15px; }
}

.st-issue {
    font-family: Arial, sans-serif;
    max-width: 210mm;
    margin: 0 auto;
    padding: 15px;
    font-size: 9pt;
}

.receipt-title {
    text-align: center;
    font-size: 20pt;
    font-weight: bold;
    margin-bottom: 30px;
}

.company-header {
    margin-bottom: 20px;
}

.company-name {
    font-size: 11pt;
    font-weight: bold;
    margin-bottom: 5px;
}

.company-details {
    font-size: 8pt;
    line-height: 1.4;
}

.doc-info-section {
    display: flex;
    justify-content: space-between;
    margin-bottom: 20px;
}

.doc-info {
    text-align: right;
    font-size: 9pt;
}

.doc-info div {
    margin-bottom: 5px;
}

.info-section {
    margin-bottom: 15px;
}

.info-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 10px;
}

.info-table td {
    border: 1px solid #000;
    padding: 6px;
    font-size: 9pt;
}

.info-label {
    background-color: #f5f5f5;
    font-weight: bold;
    width: 20%;
}

.info-value {
    width: 80%;
}

.items-table {
    width: 100%;
    border-collapse: collapse;
    margin: 15px 0;
    font-size: 8pt;
}

.items-table th {
    background-color: #f5f5f5;
    border: 1px solid #000;
    padding: 5px;
    text-align: left;
    font-weight: bold;
}

.items-table td {
    border: 1px solid #000;
    padding: 5px;
}

.text-right {
    text-align: right;
}

.text-center {
    text-align: center;
}

.total-row {
    font-weight: bold;
    background-color: #f9f9f9;
}

.amount-words {
    margin: 10px 0;
    font-size: 8pt;
    text-transform: uppercase;
}

.amount-label {
    font-weight: bold;
    float: right;
    margin-right: 20px;
}

.signature-section {
    display: flex;
    justify-content: space-between;
    margin-top: 40px;
    padding-top: 20px;
}

.signature-box {
    text-align: center;
}

.signature-line {
    border-top: 1px solid #000;
    margin-top: 50px;
    padding-top: 5px;
    font-weight: bold;
    font-size: 9pt;
    min-width: 150px;
}

.footer-info {
    margin-top: 20px;
    font-size: 8pt;
}
